# CREATE DATABASE customer_behavior;
USE customer_behavior;
select * from customer limit 20;
-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) AS revenue FROM customer
GROUP BY gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount FROM customer
WHERE discount_applied = "Yes"
	AND purchase_amount > (
		SELECT AVG(purchase_amount) FROM customer
        )
LIMIT 50;

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased, AVG(review_rating), COUNT(*) FROM customer
GROUP BY item_purchased
HAVING COUNT(*) >= 20 -- optional
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping
SELECT shipping_type, AVG(purchase_amount) FROM customer
WHERE shipping_type IN ("Express", "Standard")
GROUP BY shipping_type;

-- Q5. Do subscibed customers spend more? Compare average spend and total revenue between subscibers and non-subscribers
SELECT subscription_status, ROUND(AVG(purchase_amount), 2) AS "Average spend", SUM(purchase_amount) AS "Total revenue", COUNT(customer_id) AS "Total customers" FROM customer
GROUP BY subscription_status;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select * from customer LIMIT 20;
SELECT item_purchased,
	ROUND(SUM(CASE WHEN  discount_applied = "Yes" THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS Percentage
FROM customer
GROUP BY item_purchased
ORDER BY Percentage DESC
LIMIT 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total
-- number Of previous purchases, and show the count of each segment.
SELECT
CASE WHEN previous_purchases = 1 THEN "New"
    WHEN previous_purchases BETWEEN 2 AND 10 THEN "Returning"
    ELSE "Loyal" END AS Customer_type,
    COUNT(*)
FROM customer
GROUP BY Customer_type;

-- Q8. What are the top 3 most purchased products within each category.
WITH top_items AS (
SELECT
category, item_purchased, COUNT(customer_id) as total_sales,
	(RANK() OVER (PARTITION BY category ORDER BY SUM(purchase_amount) DESC)) AS ranked
FROM customer
GROUP BY category, item_purchased)
SELECT * from top_items WHERE ranked <= 3;
